/**
 * Admin API Utility — Ya Hala E-Portal
 *
 * Centralised helper for all admin-only API calls.
 * Every call made through adminFetch() automatically carries:
 *   - Authorization: Bearer <publicAnonKey>   (required by Supabase Edge Functions)
 *   - X-Admin-Token: <session token>          (server-side admin identity proof)
 *
 * The session token is a UUID generated by the server on admin login,
 * stored server-side in KV with a 24-hour expiry, and kept client-side
 * in sessionStorage (cleared when the browser tab/window is closed).
 */

import { projectId, publicAnonKey } from './supabase/info';

const ADMIN_TOKEN_KEY = 'ya_hala_admin_token';

/* ── Token helpers ────────────────────────────────────────────────────────── */

export function setAdminToken(token: string): void {
  try { sessionStorage.setItem(ADMIN_TOKEN_KEY, token); } catch { /* ignore */ }
}

export function getAdminToken(): string | null {
  try { return sessionStorage.getItem(ADMIN_TOKEN_KEY); } catch { return null; }
}

export function clearAdminToken(): void {
  try {
    // Also invalidate the token server-side (fire-and-forget)
    const token = sessionStorage.getItem(ADMIN_TOKEN_KEY);
    if (token) {
      fetch(
        `https://${projectId}.supabase.co/functions/v1/make-server-fdcde35a/auth/logout`,
        {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${publicAnonKey}`,
            'X-Admin-Token': token
          }
        }
      ).catch(() => { /* ignore network errors during logout */ });
    }
    sessionStorage.removeItem(ADMIN_TOKEN_KEY);
  } catch { /* ignore */ }
}

export function hasAdminToken(): boolean {
  return !!getAdminToken();
}

/* ── Admin-authenticated fetch ────────────────────────────────────────────── */

/**
 * Drop-in replacement for fetch() when calling /admin/* endpoints.
 *
 * Usage:
 *   const res = await adminFetch('/admin/employees');
 *   const res = await adminFetch('/admin/employees', { method: 'POST', body: JSON.stringify({...}) });
 *
 * Automatically handles:
 *   - Full URL construction (projectId prefix)
 *   - Authorization header
 *   - X-Admin-Token header
 *   - Content-Type: application/json (skipped for FormData uploads)
 */
export async function adminFetch(path: string, init: RequestInit = {}): Promise<Response> {
  const token      = getAdminToken();
  const isFormData = init.body instanceof FormData;

  const baseHeaders: Record<string, string> = {
    'Authorization': `Bearer ${publicAnonKey}`,
    ...(token       ? { 'X-Admin-Token': token }             : {}),
    ...(isFormData  ? {}                                      : { 'Content-Type': 'application/json' }),
  };

  const url = `https://${projectId}.supabase.co/functions/v1/make-server-fdcde35a${path}`;
  const reqInit: RequestInit = {
    ...init,
    headers: {
      ...baseHeaders,
      ...(init.headers as Record<string, string> || {}),
    },
  };

  // Retry up to 3 times for transient 502 / network errors
  const MAX_RETRIES = 3;
  let lastError: unknown;
  for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
    try {
      const res = await fetch(url, reqInit);
      if (res.status === 502 && attempt < MAX_RETRIES - 1) {
        // Transient gateway error — retry after backoff
        await new Promise(r => setTimeout(r, 400 * Math.pow(2, attempt)));
        continue;
      }
      return res;
    } catch (err: any) {
      lastError = err;
      const msg = String(err?.message || '');
      const isTransient = msg.includes('fetch') || msg.includes('network') || msg.includes('Failed');
      if (!isTransient || attempt === MAX_RETRIES - 1) throw err;
      await new Promise(r => setTimeout(r, 400 * Math.pow(2, attempt)));
    }
  }
  throw lastError;
}
